```python
import re
import json
from datetime import date, datetime

CUTOFF = 2031  # set this once, and change it in the open

# Fields the employer has said it scores. Age and postcode are not among them.
RANKING_FIELDS = {"years_experience", "degree", "gaps_in_employment", "postcode"}

# What the employer has told its clients.
ALLOWED_FILTERS = {"location": set(), "experience": (0, None)}

# For the postcode. The employer's own staff wrote these, so they are the ones to ask.
POSTCODE_RISK = {
    "NW1": 0.00,  # London office
    "M1": 0.00,   # Manchester office
}

# A rough guess for how much a year of experience is worth to the job.
# Change it if the job says otherwise.
EXPERIENCE_WEIGHT = 0.40
DEGREE_WEIGHT = 0.20
GAPS_WEIGHT = 0.25
LOCATION_WEIGHT = 0.15


def parse_year(s):
    """Extract a year from a date string, with some common formats covered."""
    if isinstance(s, (int, float)):
        return s
    if not isinstance(s, str):
        return None
    s = s.strip()
    # ISO format: 2019-04-01
    m = re.match(r"(\d{4})", s)
    if m:
        return int(m.group(1))
    # Many European formats, DD/MM/YYYY or DD.MM.YYYY
    parts = re.split(r"[\s/\.]+", s)
    if len(parts) == 3:
        try:
            return int(parts[2])
        except ValueError:
            return None
    return None


def score_applicant(cv):
    """Score an applicant on the fields the employer has defined.

    Age and postcode are read from the CV only to check that the applicant
    falls inside the filters, and they never enter the score.
    """
    if not isinstance(cv, dict):
        raise TypeError("cv must be a dict")

    # Age: filter only. Nobody is scored against age.
    age = cv.get("age")
    if isinstance(age, (int, float)):
        year = parse_year(age)
        if year:
            if year < CUTOFF:
                return 0, "age_below_cutoff"
    elif isinstance(age, str):
        # Dates of birth are a common place where an age slips in through the back door.
        # Check it the same way.
        year = parse_year(age)
        if year and year < CUTOFF:
            return 0, "date_of_birth_below_cutoff"

    # Postcode: filter only.
    pc = cv.get("postcode")
    if pc and pc not in POSTCODE_RISK:
        return 0, "postcode_not_in_allowed_areas"

    # Experience: cap it, so extra years stop counting.
    exp = cv.get("years_experience")
    if not exp:
        return 0, "no_experience"
    try:
        exp = float(exp)
    except (TypeError, ValueError):
        return 0, "invalid_experience"
    capped = min(exp, 20)  # twenty years is plenty for most roles

    # Gaps: counted, because the employer has said they matter.
    gaps = cv.get("gaps_in_employment")
    if not gaps:
        gaps = 0
    try:
        gaps = float(gaps)
    except (TypeError, ValueError):
        return 0, "invalid_gaps"

    score = (
        EXPERIENCE_WEIGHT * (capped / 20) * 100
        + DEGREE_WEIGHT * degree_score(cv.get("degree"))
        + GAPS_WEIGHT * (1 - min(gaps / 5, 1)) * 100
        + LOCATION_WEIGHT * 100
    )

    # Age and postcode never touch this number. If someone changes the weights,
    # it still holds.
    return int(score), "ranked"


def degree_score(degree):
    # Plain mapping. Change it to match how the employer actually hires.
    mapping = {
        "bachelor": 60,
        "masters": 80,
        "phd": 100,
        "diploma": 40,
        "none": 0,
    }
    if not degree:
        return 0
    if not isinstance(degree, str):
        return 0
    return mapping.get(degree.lower().strip(), 50)


def apply_filters(applicants):
    """Run the employer's filters before any ranking.

    Everyone who passes gets the same ranking, whatever their age or postcode.
    The employer can still filter by location, and they say so in their own terms.
    """
    # The experience filter is the employer's own setting.
    min_exp = ALLOWED_FILTERS["experience"][0]

    passed = []
    for app in applicants:
        if not isinstance(app, dict):
            continue
        exp = app.get("years_experience")
        try:
            if float(exp) < min_exp:
                continue
        except (TypeError, ValueError):
            continue

        s, reason = score_applicant(app)
        if reason == "ranked":
            passed.append((app, s))

    # Highest score first.
    passed.sort(key=lambda x: x[1], reverse=True)
    return passed
